import sympy
from sympy import QQ, GF
from sympy.ntheory import totient
from sympy.polys import cyclotomic_poly
from sympy.abc import x

# Top-level setup
# No specific named bindings are required for this field theory conjecture,
# but we use sympy's QQ and GF which are imported above.

CONDITION_LABELS = [
    "H_1: F is a field",
    "H_2: The characteristic of F does not divide n",
    "H_3: K is the splitting field of x^n - 1 over F",
    "¬Q: K is not generated by a primitive n-th root of unity over F"
]

N_HYP = 3
NEG_Q_INDEX = 3

def conditions(witness):
    try:
        if isinstance(witness, dict):
            F = witness.get('F')
            n = witness.get('n')
            K = witness.get('K')
        else:
            F, n, K = witness
    except Exception:
        return [False, False, False, False]

    # H1: F is a field
    try:
        h1 = bool(getattr(F, 'is_Field', False))
    except Exception:
        h1 = False

    # H2: The characteristic of F does not divide n
    try:
        char = F.characteristic()
        if char == 0:
            h2 = (n != 0)
        else:
            h2 = (n % char != 0)
    except Exception:
        h2 = False

    # H3: K is the splitting field of x^n - 1 over F
    try:
        h3 = False
        if isinstance(n, int) and n != 0:
            abs_n = abs(n)
            if F == QQ:
                deg = totient(abs_n)
                if deg == 1:
                    h3 = (K == QQ)
                else:
                    poly = cyclotomic_poly(abs_n, x)
                    if hasattr(K, 'ext') and K.domain == QQ:
                        h3 = (K.ext.minpoly.as_expr(x) == poly)
            elif getattr(F, 'is_FiniteField', False):
                q = F.order
                if abs_n == 1:
                    d = 1
                else:
                    d = 1
                    val = q % abs_n
                    while val != 1 and d <= abs_n:
                        val = (val * q) % abs_n
                        d += 1
                if getattr(K, 'is_FiniteField', False) and K.characteristic() == F.characteristic():
                    h3 = (K.order == q**d)
    except Exception:
        h3 = False

    # neg_Q: K != F(\zeta) for some primitive n-th root of unity in K
    # (If n <= 0, there is no primitive n-th root of unity, so the conclusion fails)
    try:
        neg_q = True
        if isinstance(n, int) and n > 0:
            if F == QQ:
                if K == QQ:
                    if n in (1, 2):
                        neg_q = False
                else:
                    poly = cyclotomic_poly(n, x)
                    if hasattr(K, 'ext') and K.domain == QQ:
                        if K.ext.minpoly.as_expr(x) == poly:
                            neg_q = False
            elif getattr(F, 'is_FiniteField', False) and getattr(K, 'is_FiniteField', False):
                if n == 1:
                    if K.order == F.order:
                        neg_q = False
                elif (K.order - 1) % n == 0:
                    q = F.order
                    k = 1
                    val = q % n
                    while val != 1 and k <= n:
                        val = (val * q) % n
                        k += 1
                    if K.order == q**k:
                        neg_q = False
    except Exception:
        neg_q = False

    return [h1, h2, h3, neg_q]